SELECT COUNT(*) as career_count FROM career_history WHERE clientId = 1389902;
SELECT COUNT(*) as edu_count FROM education_history WHERE clientId = 1389902;
SELECT organisation, LENGTH(keyResponsibilities) as resp_len FROM career_history WHERE clientId = 1389902 ORDER BY resp_len DESC LIMIT 5;

